"""Lockstep command-queue simulator.

Deterministic simulation:
  - Commands are scheduled for specific tick numbers and queued.
  - step(world) applies every command due at the current tick, ordered by
    (tick, unit_id, insertion_order), then advances unit movement.
  - All state is integer-only; identical command sets inserted in any order
    produce identical worlds (verified by a stable-repr + sha256 hash).
"""

from __future__ import annotations

import hashlib
import itertools
import reprlib
from dataclasses import dataclass, field
from typing import Iterator


@dataclass(frozen=True)
class Command:
    """A scheduled command. kind is 'move' or 'halt'."""

    tick: int          # tick at which this command executes
    unit_id: int       # target unit
    kind: str          # "move" | "halt"
    dx: int = 0        # move delta x
    dy: int = 0        # move delta y


class Unit:
    __slots__ = ("uid", "x", "y", "vx", "vy", "moving")

    def __init__(self, uid: int, x: int, y: int) -> None:
        self.uid = uid
        self.x = x
        self.y = y
        self.vx = 0
        self.vy = 0
        self.moving = False

    def stable_repr(self) -> str:
        return (
            f"Unit(uid={self.uid},x={self.x},y={self.y},"
            f"vx={self.vx},vy={self.vy},moving={self.moving})"
        )


class World:
    """Holds units plus a lockstep command queue."""

    def __init__(self) -> None:
        self.tick: int = 0
        self.units: dict[int, Unit] = {}
        self._queue: dict[tuple[int, int], list[Command]] = {}
        self._insertion_counter = itertools.count()
        # (sort_key, seq) per command so we can reproduce insertion order in repr
        self._pending: dict[int, tuple] = {}  # id(cmd-tuple) not usable; store per entry below

    def add_unit(self, uid: int, x: int, y: int) -> None:
        if uid in self.units:
            raise ValueError(f"duplicate unit id {uid}")
        self.units[uid] = Unit(uid, x, y)

    def schedule(self, cmd: Command) -> None:
        """Queue a command for execution at cmd.tick."""
        key = (cmd.tick, cmd.unit_id)
        self._queue.setdefault(key, []).append(cmd)

    def due_commands(self, tick: int) -> Iterator[Command]:
        """All commands due at `tick`, ordered by (tick, unit_id, insertion_order)."""
        for unit_id in sorted(u for (t, u) in self._queue if t == tick):
            yield from self._queue.pop((tick, unit_id))

    def step(self) -> None:
        """Apply all commands due at the current tick, then advance movement."""
        t = self.tick
        for cmd in self.due_commands(t):
            unit = self.units[cmd.unit_id]
            if cmd.kind == "move":
                unit.vx = cmd.dx
                unit.vy = cmd.dy
                unit.moving = True
            elif cmd.kind == "halt":
                unit.vx = 0
                unit.vy = 0
                unit.moving = False
            else:
                raise ValueError(f"unknown command kind {cmd.kind!r}")
        for unit in sorted(self.units.values(), key=lambda u: u.uid):
            if unit.moving:
                unit.x += unit.vx
                unit.y += unit.vy
        self.tick = t + 1

    def advance(self, ticks: int) -> None:
        for _ in range(ticks):
            self.step()

    # ---- determinism -------------------------------------------------

    def stable_repr(self) -> str:
        """Order-independent canonical representation of full state."""
        parts = [f"tick={self.tick}"]
        for uid in sorted(self.units):
            parts.append(self.units[uid].stable_repr())
        pending: list[str] = []
        for (tick, uid), cmds in sorted(self._queue.items()):
            # queue lists preserve insertion order per (tick, unit_id)
            for c in cmds:
                pending.append(
                    f"Cmd(tick={tick},unit_id={uid},kind={c.kind},dx={c.dx},dy={c.dy})"
                )
        parts.append("pending=[" + ",".join(pending) + "]")
        return "World(" + ";".join(parts) + ")"

    def hash(self) -> str:
        return hashlib.sha256(self.stable_repr().encode("utf-8")).hexdigest()

    def __repr__(self) -> str:  # pragma: no cover
        return reprlib.Repr().repr(self.stable_repr())

